import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long m = sc.nextLong();
        long b = sc.nextLong();
        long maxBananas = 0;
        for (long y = 0; y <= b; y++) {
            long x = (b - y) * m;
            long bananas = (x + 1) * (y + 1) * (x + y) / 2;
            if (bananas > maxBananas) {
                maxBananas = bananas;
            }
        }
        System.out.println(maxBananas);
    }
}
